package com.enterprise.inventory.service;

@Service
public class OrderService {
    private final InventoryRepository inventoryRepo;

    public OrderService(InventoryRepository inventoryRepo) {
        this.inventoryRepo = inventoryRepo;
    }

    @Transactional
    public OrderResponse checkoutOrder(OrderRequest request) {
        // BUG: Self-invocation skips REQUIRES_NEW proxy
        this.reserveStock(request.getItemId(), request.getQuantity());
        return new OrderResponse("SUCCESS");
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void reserveStock(Long itemId, int qty) {
        inventoryRepo.decrementStock(itemId, qty);
    }
}
